sys_variable_value.value:
(function execute(inputs, outputs) {
    var doppel = new DoppelIOCImport();
    var result = doppel.createAlertInDoppel(inputs.entity, inputs.brand, inputs.source);
    outputs.success = !!result.success;
    outputs.error = result.error || '';
    if (result.success) {
        outputs.already_existed = !!result.alreadyExisted;
        outputs.alert_id = result.data.id || '';
        outputs.brand = inputs.brand || '';  // Doppel's create response doesn't echo brand back
        outputs.doppel_link = result.data.doppel_link || '';
    }
})(inputs, outputs);

